def convertBase(num, base):
    if num == 0:
        return "0"
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    while num > 0:
        result.append(chars[num % base])
        num //= base
    return "".join(reversed(result))

