def max_subarray_sum_kadane(arr):
    best = current = arr[0]
    for x in arr[1:]:
        current = max(x, current + x)
        best = max(best, current)
    return best


def max_subarray_sum_dc(arr):
    def solve(left, right):
        if left == right:
            return arr[left]
        mid = (left + right) // 2

        left_best = solve(left, mid)
        right_best = solve(mid + 1, right)

        left_sum = 0
        left_cross = float('-inf')
        for i in range(mid, left - 1, -1):
            left_sum += arr[i]
            left_cross = max(left_cross, left_sum)

        right_sum = 0
        right_cross = float('-inf')
        for i in range(mid + 1, right + 1):
            right_sum += arr[i]
            right_cross = max(right_cross, right_sum)

        return max(left_best, right_best, left_cross + right_cross)

    return solve(0, len(arr) - 1)

def find_duplicates(arr):
    count = {}
    for x in arr:
        count[x] = count.get(x, 0) + 1

    seen = set()
    result = []
    for x in arr:
        if count[x] > 1 and x not in seen:
            seen.add(x)
            result.append(x)
    return result

