    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_str):
        return False
    year, month, day = map(int, date_str.split('-'))
    # 2. 年份范围
    if not (1 <= year <= 9999):
        return False
    # 3. 月份范围
    if not (1 <= month <= 12):
        return False
    # 4. 计算当月最大天数
    if month in (1, 3, 5, 7, 8, 10, 12):
        max_day = 31
    elif month in (4, 6, 9, 11):
        max_day = 30
    else:  # 2 月
        max_day = 29 if is_leap(year) else 28
    # 5. 日期范围
    return 1 <= day <= max_day

