def estimate_by_formula(raw_weight, loss_rate):
    """
    思路A：根据失水率公式估算成品重量。

    :param raw_weight: 原料重量（kg）
    :param loss_rate: 失水率（%），例如 12 表示 12%
    :return: 成品重量（kg）
    """
    return raw_weight * (1 - loss_rate / 100)


def estimate_by_history(raw_weight, loss_rate, historical_data):
    """
    思路B：基于历史批次数据建立经验换算关系估算成品重量。

    方法：按失水率分组求平均成品率，再对相邻失水率做线性插值。
    每个历史样本格式为 (原料重量, 失水率, 实际成品重量)。

    :param raw_weight: 当日原料重量（kg）
    :param loss_rate: 当日失水率（%）
    :param historical_data: 历史数据列表
    :return: 估算的成品重量（kg）
    """
    if not historical_data:
        raise ValueError("historical_data 不能为空")

    # 计算每个历史样本的成品率 k = 成品重量 / 原料重量
    rate_list = []
    for raw, loss, finished in historical_data:
        if raw == 0:
            continue
        rate_list.append((loss, finished / raw))

    if not rate_list:
        raise ValueError("historical_data 中没有有效的原料重量数据")

    # 按失水率分组并计算平均成品率
    groups = {}
    for loss, rate in rate_list:
        groups.setdefault(loss, []).append(rate)

    sorted_by_loss = sorted(
        (loss, sum(rates) / len(rates)) for loss, rates in groups.items()
    )

    # 如果只有一个分档，直接使用平均成品率
    if len(sorted_by_loss) == 1:
        return raw_weight * sorted_by_loss[0][1]

    losses = [p[0] for p in sorted_by_loss]
    rates = [p[1] for p in sorted_by_loss]

    # 边界处理：使用最近档位的平均成品率
    if loss_rate <= losses[0]:
        avg_rate = rates[0]
    elif loss_rate >= losses[-1]:
        avg_rate = rates[-1]
    else:
        # 找到相邻失水率区间，进行线性插值
        avg_rate = None
        for i in range(len(losses) - 1):
            if losses[i] <= loss_rate <= losses[i + 1]:
                if losses[i] == losses[i + 1]:
                    avg_rate = rates[i]
                else:
                    ratio = (loss_rate - losses[i]) / (losses[i + 1] - losses[i])
                    avg_rate = rates[i] + ratio * (rates[i + 1] - rates[i])
                break
        if avg_rate is None:
            avg_rate = rates[-1]

    return raw_weight * avg_rate

