def calculate_grade_by_records(records, weights=None):
    """按多行记录分组计算综合成绩。
    records: list of (学生, 成绩类型, 分数)，例如 [('A', '平时', 80), ('A', '期中', 85), ...]
    weights: dict，例如 {'平时': 0.3, '期中': 0.3, '期末': 0.4}
    返回每个学生的综合成绩（保留一位小数）。
    """
    if weights is None:
        weights = {'平时': 0.3, '期中': 0.3, '期末': 0.4}

    weighted_sum = {}
    weight_sum = {}

    for student, exam_type, score in records:
        weight = weights[exam_type]
        weighted_sum[student] = weighted_sum.get(student, 0) + score * weight
        weight_sum[student] = weight_sum.get(student, 0) + weight

    return {
        student: round(weighted_sum[student] / weight_sum[student], 1)
        for student in weighted_sum
    }

