def estimate_man_machine_hours(Q, P):
    """总人机工时 H = Q / P。"""
    if P <= 0:
        raise ValueError("P 必须大于 0")
    return Q / P


def estimate_hours_b(Q, P, M, S=0, speeds=None, allocations=None):
    """
    思路B：按瓶颈设备推算日历工时。
    默认 M 台设备同型且订单均分；也可传入 speeds/allocations。
    T = max_i(allocations_i / speeds_i) + S
    """
    if M <= 0:
        raise ValueError("M 必须大于 0")
    if S < 0:
        raise ValueError("S 不能为负数")

    if speeds is None:
        speeds = [P] * M
    if allocations is None:
        allocations = [Q / M] * M

    if len(speeds) != M or len(allocations) != M:
        raise ValueError("speeds 和 allocations 的长度都必须等于 M")
    if any(s <= 0 for s in speeds):
        raise ValueError("speed 必须大于 0")
    if any(q < 0 for q in allocations):
        raise ValueError("allocations 不能为负数")

    times = [q / s for q, s in zip(allocations, speeds)]
    return max(times) + S

